function renderAllReturnsTables() {
  // Recompute only the visible table. Tab entry reads current data again; no persistent result cache.
  [["dashboard","all"],["general","gen"],["domestic","dom"],["overseas","ov"],["pension","pen"]].forEach(function(entry){
    var panel=document.getElementById("panel-"+entry[0]);
    if(panel && panel.classList.contains("active")) renderReturnsTable(entry[1],entry[1]+"ReturnsTable");
  });
}
